[
{
   "text": "You scurry down into this small, sandy cave. A giant stands before you, ancient-looking spell scrolls tucked into his large coat. 

'Got something real special for sale, small one.' he calls out.",
   "options": [{
      "name": "(Continue)", "action": [{"deleteMapObject":-1}]}]
}
]

[
  {
    "text": "'I happen to have come across some extremely rare items. Spell packs of a most ancient kind - Beta. Contained within are many spells the smiths of today can't make - sixteen of them in total. This is the only place to find most of them, and those you can get elsewhere are fiercely guarded indeed. There are also many other powerful spells within. Who knows what treasures you'll find? Care to test your luck?'",
    "options": [
      {
        "name": "I'm feeling lucky. (Spend 20,0000 gold)",
        "condition": [
          { "hasGold": 20000 }
        ],
        "text": "'Come back soon - I have more for sale!'",
        "action": [
          {
            "addGold": -20000,
            "grantRewards": [
              { "type": "cardPackShop", "count": 1, "editions": ["LEB"] }
            ]
          }
        ]
      },
      {
        "name": "I'm feeling lucky. (Spend 20,0000 gold)",
        "condition": [
          { "hasGold": 20000, "not": true }
        ],
        "text": "'Afraid power like this is out of your price range for now.'",
					"options": [ { "name": "(Continue)" } ]
      },
				{
					"name": "Doesn't seem worth it.",
					"text": "'Suit yourself. Someone else will come looking for a Black Lotus if you're too poor or foolish to want one.'",
					"options": [ { "name": "(Continue)" } ]
				}
    ]
  }
]
